// The home continue rail (browse-scale D5, home-rail entity grain): ONE
// server-composed round-trip the SPA's home surface renders from — the
// caller's FULL positive-progress set grouped into touched entities (one
// card per series, films/tv items per item), scored through the SAME recs
// composition, ordered score-then-recency, THEN cut to the ≤50-CARD bound,
// each surviving entity composed into one ContinueRow. The route takes no
// parameters by design (D5's declined alternatives): the rail has no paging
// or shape-branching seam in v1.
//
// The row's two offers are constructive, never decorative — each is present
// exactly when its pick resolves, so the wire cannot carry either lie:
//
//   - `current` (the resume body) is present iff the entity's resume-max
//     pick resolves — the highest-STARTED touched row that is NOT
//     watched-ledgered. Every touched row ledgered means the position is
//     spent: the field is OMITTED from the wire (omitempty — gone, never
//     null) and the row serves as the ANCHOR CARD — the series block and
//     the next offer alone.
//   - `next` is present iff homeNextPick finds an episode strictly after
//     the entity's started-max — the highest-STARTED touched row, ledgered
//     rows INCLUDED (the last-known frontier a fully-watched series honest
//     resumes from is its final watched episode).
//
// `current` and `next` are therefore never the same item (next is strictly
// after the resume pick's own pair), and a spent position never renders.
//
// Viewer posture (6.2, the recommendation-sorting visibility mandate carried
// onto this route): every read below — the ledger read inside recsFactsFor,
// the entity walk's item reads, the scoring, the episode reads — is the
// CALLING VIEWER's, so a library outside the visible set contributes no rows
// at all (no ids, no names, no counts), and the shared namers receive
// v.ChainMutes so names and artwork mute exactly like every other
// browse-group route. The watched-ledger rows are NOT withdrawn here (the
// /progress default's withdrawal does not carry over): a completed episode
// keeps its positive progress row, and that row is the started-max anchor
// its series' pick derives from — the fused next affordance is exactly what
// the SPA's separate Next-up section consumed the served rows for. The wire
// carries no watched flag, ever; a row renders as a resume point or an
// anchor card, never both lies at once.

package api

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"math"
	"net/http"
	"strconv"

	"github.com/mellifera/mellifera/internal/access"
	"github.com/mellifera/mellifera/internal/naming"
	"github.com/mellifera/mellifera/internal/store"
)

// homeBound is D5's ≤50: the hard server-side cap on the rail's CARDS. The
// cut lands AFTER the score order (score-then-window), so a high scorer can
// never fall behind the window the way an SQL LIMIT would cut it — and at
// entity grain it spends slots on whole entities: a multi-row series eats
// ONE slot, and the cut never lands mid-series.
const homeBound = 50

// homeResponse is the wire shape for GET /api/v1/home (browse-scale D7).
type homeResponse struct {
	Continue []continueRow `json:"continue"`
}

// continueRow is ONE continue rail row: the series the current item anchors
// to (its served id, display name, artwork) beside the row's resume facts.
// A row whose item carries no series anchor — a film or tv item — serves the
// series fields as "" (honest absence, never a fabricated owner; the SPA's
// fallback chain reads the empty strings as absent) and never carries next.
type continueRow struct {
	SeriesID      string `json:"series_id"`
	SeriesDisplay string `json:"series_display_name"`
	LibraryID     int64  `json:"library_id"`
	LibraryName   string `json:"library_name"`
	// Artwork is the query-time composed poster URL (artwork): the owning
	// series' for serial rows, the item's own (with the owning-series
	// fallback) for films — resolved over the bounded row set per request,
	// never from a cache of display bytes. Absent (omitempty) when nothing
	// composes — honest absence, never a placeholder.
	Artwork string `json:"artwork,omitempty"`
	// Current is the row's resume point, built ONLY from the entity's
	// resume-max row — present iff that pick resolves (a touched row that is
	// not watched-ledgered). ABSENT on an anchor card: every touched row
	// ledgered means the position is spent, and omitempty takes the field
	// GONE from the wire — never null, never a zero-value resume point.
	Current *continueCurrent `json:"current,omitempty"`
	// Next is the next-episode offer — omitted (omitempty) when none: films
	// never carry it (an episode concept), and neither does a series whose
	// highest-started episode is also its last, or whose remaining episodes
	// carry no parseable facts.
	Next *continueNext `json:"next,omitempty"`
}

// continueCurrent is the row's resume point: the item to deep-link into, its
// served display name, the parsed episode identity when the document carries
// it, the episode's own convention title when the metadata projection
// resolves one, the stored position, and the item's ffprobe duration when
// the document stores it (omitted otherwise — the honest absence a client
// renders as a bar-less row).
type continueCurrent struct {
	ItemID          string `json:"item_id"`
	Display         string `json:"display_name"`
	Season          *int64 `json:"season,omitempty"`
	Episode         *int64 `json:"episode,omitempty"`
	EpisodeTitle    string `json:"episode_title,omitempty"`
	PositionSeconds int64  `json:"position_seconds"`
	DurationSeconds *int64 `json:"duration_seconds,omitempty"`
}

// continueNext is the row's Play-able suggestion: the episode item to
// deep-link into and the SxxEyy label composed from its raw episode facts
// (facts stay raw on the wire; only the pick moved server-side).
type continueNext struct {
	ItemID string `json:"item_id"`
	Label  string `json:"label"`
}

// home: the caller's full positive-progress set → recsFactsFor's batched
// reads → homeEntities' entity grain (one card per touched series, the
// serve law) → scoreHomeEntities' existing scorers → orderHomeEntities →
// the ≤50-CARD homeBound cut → per-entity ContinueRow composition.
//
// @Summary      Continue rail (home)
// @Tags         home
// @ID           get-home
// @Router       /home [get]
// @Success      200 {object} homeResponse
// @Failure      500 {object} errorBody
func (a *app) home(w http.ResponseWriter, r *http.Request) {
	// The caller's ledger scope (6.2): the composition below — the batched
	// reads, the entity walk's item reads, the score — is the requesting
	// viewer's own slot over its visible libraries.
	v, ctx := a.viewerFor(r)
	facts, err := a.recsFactsFor(ctx, v)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	// The entity-grain default: the full positive set groups into entities
	// (D1 — no input withdrawal), scores through the existing scorers (D5),
	// orders score-desc/recency (D6), THEN cuts to the CARD bound.
	ents, namers, err := a.homeEntities(ctx, v, facts)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	scoreHomeEntities(ents, facts, namers)
	orderHomeEntities(ents)
	if len(ents) > homeBound {
		ents = ents[:homeBound]
	}
	rows, err := a.homeRows(ctx, v, ents, namers)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	writeJSON(w, http.StatusOK, homeResponse{Continue: rows})
}

// homeRows composes the bounded entity set into ContinueRows IN SERVED
// ORDER — ONE row per entity: the resume body built ONLY from the entity's
// resume-max row (ABSENT — the anchor card — when every touched row is
// ledgered), the next pick over the entity's own pre-cut episode rows. The
// rows span libraries, and every composition leg is per-library (namerFor's
// whole-library series read, artworkFor's batched overrides read), so the
// work groups by library — the namers arrive SHARED from homeEntities (D7 —
// built once, never re-read), one library row and two batched artwork
// passes run per library, and the composed rows re-assemble in the served
// order afterwards.
func (a *app) homeRows(ctx context.Context, v access.Viewer, ents []homeEntity, namers map[int64]naming.Namer) ([]continueRow, error) {
	byLib := make(map[int64][]int, len(ents))
	for i, ent := range ents {
		byLib[ent.libID] = append(byLib[ent.libID], i)
	}
	composed := make([]continueRow, len(ents))
	for libID, idx := range byLib {
		libEnts := make([]homeEntity, len(idx))
		for j, i := range idx {
			libEnts[j] = ents[i]
		}
		rows, err := a.homeLibRows(ctx, v, libID, namers[libID], libEnts)
		if err != nil {
			return nil, err
		}
		for j, row := range rows {
			composed[idx[j]] = row
		}
	}
	return composed, nil
}

// homeLibRows composes one library's entities. Every store read here is
// either batched per library (the artwork passes) or once per entity (the
// series override, the resume body's own override point read — the DTO
// seam's documented MVP posture already prices it: itemDTOs; display-naming
// D-9); the episode rows are the entity's own pre-cut carry (D7) — the
// composer runs NO read the entity layer has not already paid for.
func (a *app) homeLibRows(ctx context.Context, v access.Viewer, libID int64, n naming.Namer, ents []homeEntity) ([]continueRow, error) {
	libName := ""
	lib, err := a.deps.Store.GetLibrary(ctx, libID, access.System())
	switch {
	case err == nil:
		libName = lib.DisplayName
	case errors.Is(err, sql.ErrNoRows):
		// The library row vanished: the shared namer above already floored
		// empty, and the display name floors with it (honest absence — the
		// same missing-library floor every namerFor call site shares).
	default:
		return nil, err
	}
	// The per-entity series overrides: storedTitle once per served entity —
	// entity grain means ONE entity per series, so this is the same
	// one-read-per-distinct-series posture today's per-row walk amortized
	// to. Composer-local state (design §Interfaces carries no override on
	// the entity between the seams).
	overrides := make(map[string]string, len(ents))
	for i := range ents {
		if !ents[i].served {
			continue
		}
		ov, err := a.storedTitle(ctx, ents[i].sr.ID)
		if err != nil {
			return nil, err
		}
		overrides[ents[i].sr.ID] = ov
	}
	// Query-time artwork over the bounded entity set (artwork D3): served
	// serial entities ride their OWNING SERIES' composition, film entities
	// ride the item leg with its lazy series fallback — both the batched
	// artworkFor passes, under the caller's mutes. A floored entity (facts
	// parsed, series unresolvable) carries NO artwork leg — honest absence,
	// never a fabricated owner.
	var serialArt, filmArt []artRow
	for i := range ents {
		switch {
		case ents[i].served:
			serialArt = append(serialArt, artRow{id: ents[i].sr.ID, doc: ents[i].sr.Document})
		case ents[i].film:
			filmArt = append(filmArt, artRow{id: ents[i].resumeItem.ID, path: ents[i].resumeItem.RelativePath, doc: ents[i].resumeItem.Document})
		}
	}
	seriesArt := map[string]string{}
	if len(serialArt) > 0 {
		if seriesArt, err = a.artworkFor(ctx, artKindSeries, serialArt, n, nil, v.ChainMutes); err != nil {
			return nil, err
		}
	}
	filmArtMap := map[string]string{}
	if len(filmArt) > 0 {
		// The item leg's lazy series-fallback read (one per library, made by
		// artworkFor only when some film resolved absent) — the same
		// closure shape itemDTOs builds.
		seriesOf := func(ctx context.Context) ([]store.Series, error) {
			return a.deps.Store.QuerySeries(ctx, libID, "", access.System())
		}
		if filmArtMap, err = a.artworkFor(ctx, artKindItem, filmArt, n, seriesOf, v.ChainMutes); err != nil {
			return nil, err
		}
	}
	// Row composition — ONE row per entity. The anchor card (hasResume
	// false: every touched row ledgered) sets the series block with current
	// ABSENT — omitempty takes the field off the wire; the resume card sets
	// current from the resume-max row alone, never from a spent position.
	out := make([]continueRow, len(ents))
	for i := range ents {
		ent := &ents[i]
		row := continueRow{
			LibraryID:   libID,
			LibraryName: libName,
		}
		if ent.served {
			row.SeriesID = ent.sr.ID
			row.SeriesDisplay = n.SeriesName(ent.sr, overrides[ent.sr.ID])
			row.Artwork = seriesArt[ent.sr.ID]
			// The next pick (never for films, never without a served
			// series): over the entity's OWN episode rows, strictly after
			// the started-max — which spans ALL touched rows, ledgered
			// included.
			if id, label, ok := homeNextPick(ent.eps, ent.startS, ent.startE); ok {
				row.Next = &continueNext{ItemID: id, Label: label}
			}
		} else if ent.film {
			row.Artwork = filmArtMap[ent.resumeItem.ID]
		}
		if ent.hasResume {
			cur := &continueCurrent{
				ItemID:          ent.resumeItem.ID,
				PositionSeconds: ent.resume.PositionSeconds,
			}
			// The raw episode identity on the wire (facts stay raw; only
			// naming and picking are server-composed) — served whenever the
			// document parses, independent of series resolution.
			if !ent.film {
				s, e := ent.resumeS, ent.resumeE
				cur.Season, cur.Episode = &s, &e
			}
			// The resume body's served display name — the SAME seam the
			// item listing stamps (toItemDTO): the row's own override over
			// the series-override-carrying namer's ItemName chain. The
			// series override is already point-read above, so it is set
			// directly (the withSeriesOverride point read would resolve the
			// identical row).
			ov, err := a.storedTitle(ctx, ent.resumeItem.ID)
			if err != nil {
				return nil, err
			}
			nn := n
			if ent.served {
				nn.SeriesOverride = overrides[ent.sr.ID]
			}
			cur.Display = nn.ItemName(ent.resumeItem, ov)
			// The episode's own convention title — the SAME projection the
			// About panel renders (metadataFor's episode group; the winner
			// namespace's title member verbatim). Any non-string floors to
			// absent — never a fabricated "".
			if !ent.film {
				if md := n.MetadataFor(ent.resumeItem.Document); md != nil {
					if ep, ok := md["episode"].(map[string]any); ok {
						if t, ok := ep["title"].(string); ok {
							cur.EpisodeTitle = t
						}
					}
				}
			}
			// The honest duration: the verbatim ffprobe fact, or nothing.
			if d, ok := homeDurationSeconds(naming.DocMap(ent.resumeItem.Document)); ok {
				cur.DurationSeconds = &d
			}
			row.Current = cur
		}
		out[i] = row
	}
	return out, nil
}

// homeNextPick is the next-episode pick, tuple parity with the watch page's
// client derivation pinned (nextup.ts nextEpisodeAfter — the exact vectors
// the SPA test pins live re-pinned here): the LOWEST (season, episode) pair
// STRICTLY AFTER the started pair, taken from the series' episode rows.
// Candidates without parseable episode facts are skipped, never fatal; the
// started pair itself (equal facts) never wins; nothing strictly after —
// none at all, or none parseable — is ok=false, the caller omits next.
func homeNextPick(eps []store.Item, startedSeason, startedEpisode int64) (itemID, label string, ok bool) {
	found := false
	var bestS, bestE int64
	for _, ep := range eps {
		_, s, e, fok := naming.EpisodeFacts(naming.DocMap(ep.Document))
		if !fok {
			continue
		}
		if !(s > startedSeason || (s == startedSeason && e > startedEpisode)) {
			continue
		}
		if !found || s < bestS || (s == bestS && e < bestE) {
			found, bestS, bestE, itemID = true, s, e, ep.ID
		}
	}
	if !found {
		return "", "", false
	}
	return itemID, fmt.Sprintf("S%02dE%02d", bestS, bestE), true
}

// homeDurationSeconds reads the item's total whole-second duration from the
// verbatim ffprobe blob — parity with the SPA's durationSeconds (Home.tsx):
// ffprobe writes format.duration as a decimal-seconds string, and the doc
// decode keeps JSON numbers as json.Number, so both shapes parse. Anything
// missing, mistyped, unparseable, non-finite, or non-positive floors to
// ok=false — the caller omits the field rather than guessing (the bar-less
// row the client renders).
func homeDurationSeconds(doc map[string]any) (int64, bool) {
	if doc == nil {
		return 0, false
	}
	ff, _ := doc["ffprobe"].(map[string]any)
	if ff == nil {
		return 0, false
	}
	format, _ := ff["format"].(map[string]any)
	if format == nil {
		return 0, false
	}
	var raw string
	switch v := format["duration"].(type) {
	case string:
		raw = v
	case json.Number:
		raw = v.String()
	default:
		return 0, false
	}
	f, err := strconv.ParseFloat(raw, 64)
	if err != nil || math.IsNaN(f) || math.IsInf(f, 0) || f <= 0 {
		return 0, false
	}
	return int64(math.Round(f)), true
}
